"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2242-01-01:1":{"b": ["Erste Zwischenzeit: beginnt", "ef148434"], "d": ["Zersplitterte Zeit vom Zerfall der Zentralgewalt des Alten Reiches bis zum Beginn des Mittleren Reiches; der Artikel betont die Übereinstimmung mit dem Dürreereignis 4.2 ka (ca. 2250 v. Chr.).", "47a3a1aa"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2499-01-01:0":{"b": ["Königreich/Kultur von Kerma (Kusch): beginnt", "f7cdc981"], "d": ["Nubisches Königreich mit Zentrum Kerma unterhalb des Dritten Katarakts; durchläuft die Phasen Alt-Kerma (~2500), Mittel- und Klassisches Kerma und endet ~1450 v. Chr. Honegger 2005: ‚Kerma Classique (vers 1500 av. J.-C.)‘, befestigte Siedlung.", "5ea1ab25"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2662-01-01:0":{"b": ["Altes Reich (Pyramidenzeit): beginnt", "9e3a1499"], "d": ["Königreich der Pyramidenzeit; nach Erdil u. a. 2025 liegt der Beginn des Alten Reiches bei ~2698–2629 v. Chr. (95 %), der Übergang zur Ersten Zwischenzeit bei ~2283–2204 v. Chr. (95 %). Die ‚Low‘-Chronologie wird in diesem Bereich nicht mehr gestützt.", "2ac5035a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3125-01-01:0":{"b": ["Naqada-Kultur: endet", "a6d98d7b"], "d": ["Prädynastische Kultur Oberägyptens nach Badari; umfasst die Phasen Naqada I–III und gelangt in Naqada IIIC mit der 1. Dynastie (Aha) zur politischen Einheit.", "8fadb99a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3499-01-01:0":{"b": ["Prä-Kerma-Kultur: beginnt", "35f09768"], "d": ["Kultur im Raum Kerma (Dongola-Strecke / unterhalb des Dritten Nilkatarakts), die vom Neolithikum zu Kerma überleitet und landwirtschaftliche Vorratsgruben sowie frühe soziale Komplexität zeigt.", "f9a036cb"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3755-01-01:0":{"b": ["Naqada-Kultur: beginnt", "1960a726"], "d": ["Prädynastische Kultur Oberägyptens nach Badari; umfasst die Phasen Naqada I–III und gelangt in Naqada IIIC mit der 1. Dynastie (Aha) zur politischen Einheit.", "8fadb99a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3949-01-01:0":{"b": ["Felsunterstand Takarkori (Tadrart Acacus): endet", "845c6a70"], "d": ["Felsunterstand im Tadrart Acacus im libyschen Fessan: ununterbrochene Stratigraphie von spätacacischen Jägern, Sammlern und Fischern (LA1, erste Besiedlung) bis zu frühen, mittleren und späten Hirten der Pastoralzeit (grüne Sahara).", "29888604"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-4699-01-01:0":{"b": ["Shaheinab-Neolithikum (Esch-Scheheinab): beginnt", "7a9cfd9c"], "d": ["Neolithische Siedlung im Zentralsudan nahe dem Nil (Haustiere, Keramik, Hohlmeißel/Gouge); definiert als Typlokalität das ‚Shaheinab-Neolithikum‘. Allgemeiner Zeitraum der Kultur 5000–3800 v. Chr.", "cd4d3a3c"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-4849-01-01:0":{"b": ["Holozäne Besiedlung des Fayum (Umgebung des Karun-Sees): endet", "53ff4e34"], "d": ["Holozäne Fischer-Jäger-Besiedlung im Fayum seit ~7350 v. Chr.; Haustiere und Kulturpflanzen seit etwa 5400 v. Chr.; neolithische Siedlungen Kom K/W 4850–4250 v. Chr.", "a016950f"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-4999-01-01:0":{"b": ["Früh-Khartum (Khartum-Mesolithikum): endet", "89b30a20"], "d": ["Mesolithikum von Jägern, Sammlern und Fischern mit Keramik (Wellenlinien) am Nilufer im Zentralsudan; von Arkell ‚Khartoum Mesolithic‘ / ‚Early Khartoum‘ genannt.", "7c5ed92c"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-7349-01-01:0":{"b": ["Holozäne Besiedlung des Fayum (Umgebung des Karun-Sees): beginnt", "eb514aa9"], "d": ["Holozäne Fischer-Jäger-Besiedlung im Fayum seit ~7350 v. Chr.; Haustiere und Kulturpflanzen seit etwa 5400 v. Chr.; neolithische Siedlungen Kom K/W 4850–4250 v. Chr.", "a016950f"]},
